	createElement,
	Component,
	createRef,
	FunctionalComponent,
	Fragment,
	RefObject,
	RefCallback
} from '../../';

// Test Fixtures
const Foo: FunctionalComponent = () => <span>Foo</span>;
class Bar extends Component {
	render() {
		return <span>Bar</span>;
	}
}

// Using Refs
class CallbackRef extends Component {
	divRef: RefCallback<HTMLDivElement> = div => {
		if (div !== null) {
			console.log(div.tagName);
		}
	};
	fooRef: RefCallback<Component> = foo => {
		if (foo !== null) {
			console.log(foo.base);
		}
	};
	barRef: RefCallback<Bar> = bar => {
		if (bar !== null) {
			console.log(bar.base);
		}
	};

	render() {
		return (
			<Fragment>
				<div ref={this.divRef} />
				<Foo ref={this.fooRef} />
				<Bar ref={this.barRef} />
			</Fragment>
		);
	}
}

